PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS companies(id INTEGER PRIMARY KEY, name TEXT NOT NULL, ruc TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','seller')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), sku TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), cost INTEGER NOT NULL CHECK(cost>=0), stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), minimum INTEGER NOT NULL DEFAULT 5 CHECK(minimum>=0), active INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,sku));
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), name TEXT NOT NULL, doc_type TEXT NOT NULL CHECK(doc_type IN ('DNI','RUC','OTRO')), document TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', UNIQUE(company_id,doc_type,document));
CREATE TABLE IF NOT EXISTS sequences(company_id INTEGER NOT NULL REFERENCES companies(id), kind TEXT NOT NULL, value INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(company_id,kind));
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), user_id INTEGER NOT NULL REFERENCES users(id), customer_id INTEGER REFERENCES customers(id), customer_snapshot TEXT NOT NULL, company_snapshot TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('boleta','factura')), number TEXT NOT NULL, subtotal INTEGER NOT NULL, tax INTEGER NOT NULL, total INTEGER NOT NULL, payment TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'registrado' CHECK(status IN ('registrado','anulado')), fiscal_status TEXT NOT NULL DEFAULT 'NO_EMITIDO', request_key TEXT NOT NULL, request_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,number), UNIQUE(company_id,request_key));
CREATE TABLE IF NOT EXISTS sale_items(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, sku TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price INTEGER NOT NULL, cost INTEGER NOT NULL, total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), product_id INTEGER NOT NULL REFERENCES products(id), user_id INTEGER NOT NULL REFERENCES users(id), delta INTEGER NOT NULL, balance INTEGER NOT NULL, reason TEXT NOT NULL, sale_id INTEGER REFERENCES sales(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), user_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS sales_company_date ON sales(company_id,created_at);
CREATE INDEX IF NOT EXISTS products_company ON products(company_id,active);
CREATE INDEX IF NOT EXISTS movements_company ON movements(company_id,id);
CREATE INDEX IF NOT EXISTS customers_company ON customers(company_id);
PRAGMA user_version=1;
